CKP_4X_input_capture_isr_81E3:
	bset <PUMP_BACKUPFLAGS,$40          ; 81E3  14 46 40      PUMP_BACKUPFLAGS .6 = 1 | IC4 4X CKP ISR entry (bank0 7E67): bset PUMP_BACKUPFLAGS.6, clear IC4F, ldd TCNT (81EB-81ED)
