	bra b1_loc_8233                     ; 8217  20 1A         goto b1_loc_8233
b1_loc_8219:
	cpd >kw_ref_period_max_run_36BC     ; 8219  1A B3 36 BC   compare D with kw_ref_period_max_run_36BC
	bhi b1_loc_8239                     ; 821D  22 1A         if D > kw_ref_period_max_run_36BC goto b1_loc_8239
	cpd >kw_ref_period_min_run_36BE     ; 821F  1A B3 36 BE   compare D with kw_ref_period_min_run_36BE
	bcs b1_loc_8239                     ; 8223  25 14         if D < kw_ref_period_min_run_36BE goto b1_loc_8239
