	bhi b1_loc_8239                     ; 822B  22 0C         if D > kw_ref_period_max_crank_36C0 goto b1_loc_8239
	cpd >kw_ref_period_min_crank_36C2   ; 822D  1A B3 36 C2   compare D with kw_ref_period_min_crank_36C2
