; do_egr_igain
;   analysis [high]: EGR integrator: gain from tbl2D_EGR_INTEGRAL_GAIN (axis = baro margin computed in
;        EGR_control) * |error|, scaled, added to or subtracted from EGR_INTEG (clamped 0..7FFF). The integrator
;        is frozen when EGR is forced (FLAGS2.7) or the duty is saturated in the same direction (anti-windup).
;   OBD1 do_egr_igain (match 0.95 p1-global)
;   called from: EGR_control
; ----------------------------------------------------------------------------
do_egr_igain:
	ldx #tbl2D_EGR_INTEGRAL_GAIN_20EA   ; ADA5  CE 20 EA      X = &tbl2D_EGR_INTEGRAL_GAIN_20EA | OBD1: flat table, 0e...0e
	jsr >lookup_2D_table                ; ADA8  BD 6D 06      A = 2D lookup tbl2D_EGR_INTEGRAL_GAIN_20EA[A]
	ldab >EGR_ERROR                     ; ADAB  F6 19 70      B = EGR_ERROR
	mul                                 ; ADAE  3D            D = A * B
	ldx #$8100                          ; ADAF  CE 81 00      X = $8100(33024)
	jsr >MUL32                          ; ADB2  BD 6A 3F      call MUL32
	tst >EGR_ERROR_SIGN                 ; ADB5  7D 19 71      test EGR_ERROR_SIGN
	bpl b1_loc_ADC6                     ; ADB8  2A 0C         if EGR_ERROR_SIGN >= 0 (signed) goto b1_loc_ADC6
	subd >EGR_INTEG                     ; ADBA  B3 19 72      D -= EGR_INTEG
	coma                                ; ADBD  43            A = ~A
	comb                                ; ADBE  53            B = ~B
	addd #$0001                         ; ADBF  C3 00 01      D += $0001(1)
	bmi b1_loc_ADD2                     ; ADC2  2B 0E         if result < 0 (signed) goto b1_loc_ADD2
	bra b1_loc_ADD5                     ; ADC4  20 0F         goto b1_loc_ADD5
b1_loc_ADC6:
	addd >EGR_INTEG                     ; ADC6  F3 19 72      D += EGR_INTEG
	bvc b1_loc_ADD0                     ; ADC9  28 05         if no overflow goto b1_loc_ADD0
	bpl b1_loc_ADD2                     ; ADCB  2A 05         if result >= 0 (signed) goto b1_loc_ADD2
	ldd #$7FFF                          ; ADCD  CC 7F FF      D = $7FFF(32767)
b1_loc_ADD0:
	bpl b1_loc_ADD5                     ; ADD0  2A 03         if result >= 0 (signed) goto b1_loc_ADD5
b1_loc_ADD2:
	ldd #$0000                          ; ADD2  CC 00 00      D = $0000(0)
b1_loc_ADD5:
	xgdx                                ; ADD5  8F            swap D <-> X
	brset <FLAGS2,$80,b1_loc_ADE8       ; ADD6  12 4A 80 0E   if FLAGS2 .7 EGR forced/open-loop (integrator frozen) set goto b1_loc_ADE8 | anti-windup: keep old integrator when forced or duty saturated in error direction
