	beq b1_loc_ADE3                     ; ADDD  27 04         if A == 0 goto b1_loc_ADE3
	inca                                ; ADDF  4C            A++
	bne b1_loc_ADEB                     ; ADE0  26 09         if A != 0 goto b1_loc_ADEB
	deca                                ; ADE2  4A            A--
b1_loc_ADE3:
	cmpa >EGR_ERROR_SIGN                ; ADE3  B1 19 71      compare A with EGR_ERROR_SIGN
	beq b1_loc_ADEB                     ; ADE6  27 03         if A == EGR_ERROR_SIGN goto b1_loc_ADEB
b1_loc_ADE8:
	ldx >EGR_INTEG                      ; ADE8  FE 19 72      X = EGR_INTEG
b1_loc_ADEB:
