	brset <FLAGS2,$80,b1_loc_AE44       ; AE2C  12 4A 80 14   if FLAGS2 .7 EGR forced/open-loop (integrator frozen) set goto b1_loc_AE44
	brset <diag_misc_flags,$02,b1_loc_AE68; AE30  12 C7 02 34   if diag_misc_flags .1 set goto b1_loc_AE68
